import stats from "@/lib/data/country-stats.json";

export const FLAG_COLOURS = ["red", "white", "blue", "green", "yellow", "black", "orange"] as const;
export type FlagColour = (typeof FLAG_COLOURS)[number];
/**
 * Generated by scripts/build-country-stats.ts. A null number means the source has no value, so the country never fits cards on that stat.
 * timezoneCount is the number of distinct standard UTC offsets across the country's IANA zones (more than one = "multiple time zones").
 * flagColours uses the fixed palette; light blue counts as blue, maroon as red, gold as yellow.
 */
export type CountryStat = {
  population: number | null; gdpUsd: number | null; gdpPerCapitaUsd: number | null;
  timezoneCount: number | null; flagColours: FlagColour[];
};
const table = stats as unknown as Record<string, CountryStat>;
export function countryStat(code: string): CountryStat | null {
  return table[code.toUpperCase()] ?? null;
}
